// GENERATED – Quran text: Tanzil (Simple, Hafs) via quran-api; translations: Pickthall (en), Diyanet (tr), Hamidullah (fr), Piccardo (it), Bubenheim & Elyas (de), Siregar (nl), Cortes (es).
// Adhkar: Hisn al-Muslim wording (Arabic). Translations of adhkar prepared for this app.
import Foundation

struct Dhikr: Identifiable {
    let id: String
    let arabic: String
    let ref: String
    let times: Int
    let translations: [String: String]
}

enum AzkharData {
    static func items(_ cat: String) -> [Dhikr] {
        switch cat {
        case "morning": return [
            Dhikr(id: "morning-kursi", arabic: "﴿ اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ ﴾", ref: "Quran 2:255 · Al-Baqarah", times: 1, translations: ["en": "Allah! There is no deity save Him, the Alive, the Eternal. Neither slumber nor sleep overtaketh Him. Unto Him belongeth whatsoever is in the heavens and whatsoever is in the earth. Who is he that intercedeth with Him save by His leave? He knoweth that which is in front of them and that which is behind them, while they encompass nothing of His knowledge save what He will. His throne includeth the heavens and the earth, and He is never weary of preserving them. He is the Sublime, the Tremendous", "tr": "Allah, O'ndan başka tanrı olmayan, kendisini uyuklama ve uyku tutmayan, diri, her an yaratıklarını gözetip durandır. Göklerde olan ve yerde olan ancak O'nundur. O'nun izni olmadan katında şefaat edecek kimdir? Onların işlediklerini ve işleyeceklerini bilir, dilediğinden başka ilminden hiçbir şeyi kavrayamazlar. Hükümranlığı gökleri ve yeri kaplamıştır, onların gözetilmesi O'na ağır gelmez. O yücedir, büyüktür", "fr": "Allah! Point de divinité à part Lui, le Vivant, Celui qui subsiste par lui-même «Al-Qayyûm». Ni somnolence ni sommeil ne Le saisissent. A Lui appartient tout ce qui est dans les cieux et sur la terre. Qui peut intercéder auprès de Lui sans Sa permission? Il connaît leur passé et leur futur. Et, de Sa science, ils n'embrassent que ce qu'Il veut. Son Trône «Kursiy», déborde les cieux et la terre, dont la garde ne Lui coûte aucune peine. Et Il est le Très Haut, le Très Grand", "it": "Allah! Non c'è altro dio che Lui, il Vivente, l'Assoluto. Non Lo prendon mai sopore, né sonno. A Lui appartiene tutto quello che è nei cieli e sulla terra. Chi può intercedere presso di Lui senza il Suo permesso? Egli conosce quello che è davanti a loro e quello che è dietro di loro e, della Sua scienza, essi apprendono solo ciò che Egli vuole. Il Suo Trono è più vasto dei cieli e della terra, e custodirli non Gli costa sforzo alcuno. Egli è l'Altissimo, l'Immenso", "de": "Allah - es gibt keinen Gott außer Ihm, dem Lebendigen und Beständigen. Ihn überkommt weder Schlummer noch Schlaf. Ihm gehört (alles), was in den Himmeln und was auf der Erde ist. Wer ist es denn, der bei Ihm Fürsprache einlegen könnte - außer mit Seiner Erlaubnis? Er weiß, was vor ihnen und was hinter ihnen liegt, sie aber umfassen nichts von Seinem Wissen - außer, was Er will. Sein Thronschemel umfaßt die Himmel und die Erde, und ihre Behütung beschwert Ihn nicht. Er ist der Erhabene und Allgewaltige", "nl": "Allah, er is geen god dan Hij, de Levende, de Zelfstandige, sluimer noch slaap kan Hem treffen, aan Hem behoort toe wat er in de hemelen en wat er op de aarde is. Wie is degene die van voorspraak is bij Hem zonder Zijn verlof? Hij kent wat er voor hen is en wat er achter hen is. En zij kunnen niets van Zijn Kennis omvatten, behalve wat Hij wil. En Zijn Zetel strekt zich uit over de Hemelen en de Aarde en het waken over beide vermoeit Hem niet. En Hij is de Verhevene, de Almachtige", "es": "¡Alá! No hay más dios que El. el Viviente, el Subsistente. Ni la somnolencia ni el sueño se apoderan de Él. Suyo es lo que está en los cielos y en la tierra. ¿Quién podrá interceder ante Él si no es con Su permiso? Conoce su pasado y su futuro, mientras que ellos no abarcan nada de Su ciencia, excepto lo que Él quiere. Su Trono se extiende sobre los cielos y sobre la tierra y su conservación no le resulta onerosa. Él es el Altísimo, el Grandioso"]),
            Dhikr(id: "morning-ikh", arabic: "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ\nقُلْ هُوَ اللَّهُ أَحَدٌ ﴿١﴾\nاللَّهُ الصَّمَدُ ﴿٢﴾\nلَمْ يَلِدْ وَلَمْ يُولَدْ ﴿٣﴾\nوَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ ﴿٤﴾", ref: "Quran 112 · Al-Ikhlas", times: 3, translations: ["en": "1. Say: He is Allah, the One\n2. Allah, the eternally Besought of all\n3. He begetteth not nor was begotten\n4. And there is none comparable unto Him", "tr": "1. De ki: O Allah bir tektir\n2. Allah her şeyden müstağni ve her şey O'na muhtaçtır\n3. O doğurmamış ve doğmamıştır\n4. Hiçbir şey O'na denk değildir", "fr": "1. Dis: «Il est Allah, Unique\n2. Allah, Le Seul à être imploré pour ce que nous désirons\n3. Il n'a jamais engendré, n'a pas été engendré non plus\n4. Et nul n'est égal à Lui»", "it": "1. Di’: “Egli Allah è Unico\n2. Allah è l’Assoluto\n3. Non ha generato, non è stato generato\n4. e nessuno è eguale a Lui”", "de": "1. Sag: Er ist Allah, ein Einer\n2. Allah, der Überlegene\n3. Er hat nicht gezeugt und ist nicht gezeugt worden\n4. und niemand ist Ihm jemals gleich", "nl": "1. Zeg: \"Hij is Allah, de Enige\n2. Allah is de Enige van Wie al het geschapene afhankelijk is\n3. Hij heeft niet verwekt en is niet verwekt\n4. En niet één is aan Hem gelijkwaardig", "es": "1. Di: «¡Él es Alá, Uno\n2. Dios, el Eterno\n3. No ha engendrado, ni ha sido engendrado\n4. No tiene par»"]),
            Dhikr(id: "morning-fal", arabic: "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ\nقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ﴿١﴾\nمِنْ شَرِّ مَا خَلَقَ ﴿٢﴾\nوَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ﴿٣﴾\nوَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ﴿٤﴾\nوَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ ﴿٥﴾", ref: "Quran 113 · Al-Falaq", times: 3, translations: ["en": "1. Say: I seek refuge in the Lord of the Daybreak\n2. From the evil of that which He created\n3. From the evil of the darkness when it is intense\n4. And from the evil of malignant witchcraft\n5. And from the evil of the envier when he envieth", "tr": "De ki: \"Yaratıkların şerrinden, bastırdığı zaman karanlığın şerrinden, düğümlere nefes eden büyücülerin şerrinden, hased ettiği zaman hasedcilerin şerrinden, tan yerini ağartan Rabbe sığınırım", "fr": "1. Dis: «Je cherche protection auprès du Seigneur de l'aube naissante\n2. contre le mal des êtres qu'Il a créés\n3. contre le mal de l'obscurité quand elle s'approfondit\n4. contre le mal de celles qui soufflent [les sorcières] sur les nœuds\n5. et contre le mal de l'envieux quand il envie»", "it": "1. Di’: “Mi rifugio nel Signore dell’alba nascente\n2. contro il male che ha creato\n3. e contro il male dell’oscurità che si estende\n4. e contro il male delle soffianti sui nodi\n5. e contro il male dell’invidioso quando invidia”", "de": "1. Sag: Ich nehme Zuflucht beim Herrn des Tagesanbruchs\n2. vor dem Übel dessen, was Er erschaffen hat\n3. und vor dem Übel der Dunkelheit, wenn sie zunimmt\n4. und vor dem Übel der Knotenanbläserinnen\n5. und vor dem Übel eines (jeden) Neidenden, wenn er neidet", "nl": "1. Zeg: \"Ik zoek bescherming bij de Heer der dageraad\n2. Tegen het kwaad dat Hij geschapen heeft\n3. En tegen het kwaad van de donkere nacht wanneer hij aanbreekt\n4. En tegen het kwaad van hen die op knopen blazen\n5. En tegen het kwaad van een jaloerse wanneer deze jaloers is", "es": "1. Di: «Me refugio en el Señor del alba\n2. del mal que hacen sus criaturas\n3. del mal de la oscuridad cuando se extiende\n4. del mal de las que soplan en los nudos\n5. del mal envidioso cuando envidia»"]),
            Dhikr(id: "morning-nas", arabic: "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ\nقُلْ أَعُوذُ بِرَبِّ النَّاسِ ﴿١﴾\nمَلِكِ النَّاسِ ﴿٢﴾\nإِلَٰهِ النَّاسِ ﴿٣﴾\nمِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ﴿٤﴾\nالَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ﴿٥﴾\nمِنَ الْجِنَّةِ وَالنَّاسِ ﴿٦﴾", ref: "Quran 114 · An-Nas", times: 3, translations: ["en": "1. Say: I seek refuge in the Lord of mankind\n2. The King of mankind\n3. The god of mankind\n4. From the evil of the sneaking whisperer\n5. Who whispereth in the hearts of mankind\n6. Of the jinn and of mankind", "tr": "De ki: \"İnsanlardan ve cinlerden ve insanların gönüllerine vesvese veren o sinsi vesvesecinin şerrinden, insanların Tanrısı, insanların Hükümranı ve insanların Rabbi olan Allah'a sığınırım", "fr": "1. Dis: «Je cherche protection auprès du Seigneur des hommes\n2. Le Souverain des hommes\n3. Dieu des hommes\n4. contre le mal du mauvais conseiller, furtif\n5. qui souffle le mal dans les poitrines des hommes\n6. qu'il (le conseiller) soit un djinn, ou un être humain»", "it": "1. Di’: “Mi rifugio nel Signore degli uomini\n2. Re degli uomini\n3. Dio degli uomini\n4. contro il male del sussurratore furtivo\n5. che soffia il male nei cuori degli uomini\n6. che [venga] dai dèmoni o dagli uomini”", "de": "1. Sag: Ich nehme Zuflucht beim Herrn der Menschen\n2. dem König der Menschen\n3. dem Gott der Menschen\n4. vor dem Übel des Einflüsterers, des Davonschleichers\n5. der in die Brüste der Menschen einflüstert\n6. von den Ginn und den Menschen", "nl": "1. Zeg: \"Ik zoek bescherming bij de Heer van de mensen\n2. De Koning van de mensen\n3. De God van de mensen\n4. Tegen het kwaad van de wegsluipende influisteraar\n5. Degene die in de harten van de mensen influistert\n6. Van de Djinn's en de mensen", "es": "1. Di: «Me refugio en el Señor de los hombres\n2. el Rey de los hombres\n3. el Dios de los hombres\n4. del mal de la insinuación, del que se escabulle\n5. que insinúa en el ánimo de los hombres\n6. sea genio, sea hombre»"]),
            Dhikr(id: "morning-asbahna", arabic: "أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لاَ إِلَهَ إلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذَا الْيَوْمِ وَخَيرَ مَا بَعْدَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذَا الْيَوْمِ وَشَرِّ مَا بَعْدَهُ، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ", ref: "Hisn al-Muslim", times: 1, translations: ["en": "We have reached the morning and the dominion belongs to Allah. Praise is for Allah. None has the right to be worshipped but Allah alone, with no partner. His is the dominion and His is the praise, and He is over all things capable. My Lord, I ask You for the good of this day and the good of what follows it, and I seek refuge in You from the evil of this day and the evil of what follows it. My Lord, I seek refuge in You from laziness and the evil of old age. My Lord, I seek refuge in You from punishment in the Fire and punishment in the grave.", "tr": "Sabaha erdik, mülk de Allah’ın olarak sabaha erdi. Hamd Allah’a mahsustur. Allah’tan başka ilah yoktur; O tektir, ortağı yoktur. Mülk O’nundur, hamd O’na aittir ve O her şeye kadirdir. Rabbim! Senden bu günün hayrını ve bundan sonrasının hayrını isterim; bu günün şerrinden ve bundan sonrasının şerrinden sana sığınırım. Rabbim! Tembellikten ve yaşlılığın kötülüğünden sana sığınırım. Rabbim! Cehennemdeki azaptan ve kabirdeki azaptan sana sığınırım.", "fr": "Nous voici au matin et la royauté appartient à Allah. Louange à Allah. Il n’y a de divinité digne d’adoration qu’Allah, l’Unique, sans associé. À Lui la royauté, à Lui la louange, et Il est capable de toute chose. Seigneur, je Te demande le bien de ce jour et le bien de ce qui le suit, et je cherche refuge auprès de Toi contre le mal de ce jour et le mal de ce qui le suit. Seigneur, je cherche refuge auprès de Toi contre la paresse et les maux de la vieillesse. Seigneur, je cherche refuge auprès de Toi contre le châtiment du Feu et le châtiment de la tombe.", "it": "Siamo giunti al mattino e il regno appartiene ad Allah. La lode è per Allah. Non vi è divinità degna di adorazione all’infuori di Allah, Unico, senza associati. A Lui appartiene il regno, a Lui la lode, ed Egli è onnipotente su ogni cosa. Mio Signore, Ti chiedo il bene di questo giorno e il bene di ciò che lo segue, e cerco rifugio in Te dal male di questo giorno e dal male di ciò che lo segue. Mio Signore, cerco rifugio in Te dalla pigrizia e dai mali della vecchiaia. Mio Signore, cerco rifugio in Te dal castigo del Fuoco e dal castigo della tomba.", "de": "Wir sind in den Morgen gelangt, und die Herrschaft gehört Allah. Lob gebührt Allah. Es gibt keinen Gott, der anzubeten ist, außer Allah, dem Einen, der keinen Teilhaber hat. Ihm gehört die Herrschaft, Ihm gebührt das Lob, und Er hat Macht über alle Dinge. Mein Herr, ich bitte Dich um das Gute dieses Tages und das Gute dessen, was danach kommt, und ich suche Zuflucht bei Dir vor dem Bösen dieses Tages und dem Bösen dessen, was danach kommt. Mein Herr, ich suche Zuflucht bei Dir vor Faulheit und den Übeln des Alters. Mein Herr, ich suche Zuflucht bei Dir vor der Strafe im Feuer und der Strafe im Grab.", "nl": "Wij zijn aan de ochtend toegekomen en de heerschappij behoort aan Allah toe. Lof zij Allah. Er is geen god die het recht heeft aanbeden te worden behalve Allah, de Enige, zonder deelgenoot. Aan Hem behoort de heerschappij, aan Hem komt de lof toe en Hij heeft macht over alle dingen. Mijn Heer, ik vraag U om het goede van deze dag en het goede van wat erop volgt, en ik zoek toevlucht bij U tegen het kwade van deze dag en het kwade van wat erop volgt. Mijn Heer, ik zoek toevlucht bij U tegen luiheid en de kwalen van de ouderdom. Mijn Heer, ik zoek toevlucht bij U tegen de straf in het Vuur en de straf in het graf.", "es": "Hemos llegado a la mañana y el dominio pertenece a Allah. La alabanza es para Allah. No hay más divinidad digna de adoración que Allah, Único, sin asociado. Suyo es el dominio y Suya es la alabanza, y Él tiene poder sobre todas las cosas. Señor mío, Te pido el bien de este día y el bien de lo que viene después, y me refugio en Ti del mal de este día y del mal de lo que viene después. Señor mío, me refugio en Ti de la pereza y de los males de la vejez. Señor mío, me refugio en Ti del castigo del Fuego y del castigo de la tumba."]),
            Dhikr(id: "morning-bika", arabic: "اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ وَإِلَيْكَ النُّشُورُ", ref: "Hisn al-Muslim", times: 1, translations: ["en": "O Allah, by You we have reached the morning, by You we reach the evening, by You we live, by You we die, and to You is the resurrection.", "tr": "Allah’ım! Seninle sabaha erdik, seninle akşama ereriz; seninle yaşar, seninle ölürüz ve dönüş sanadır.", "fr": "Ô Allah, c’est par Toi que nous atteignons le matin, par Toi que nous atteignons le soir, par Toi que nous vivons, par Toi que nous mourons, et c’est vers Toi que sera la résurrection.", "it": "O Allah, grazie a Te siamo giunti al mattino, grazie a Te giungiamo alla sera, grazie a Te viviamo e grazie a Te moriamo, e a Te sarà la resurrezione.", "de": "O Allah, durch Dich sind wir in den Morgen gelangt, durch Dich gelangen wir in den Abend, durch Dich leben wir, durch Dich sterben wir, und zu Dir ist die Auferstehung.", "nl": "O Allah, door U zijn wij aan de ochtend toegekomen, door U komen wij aan de avond toe, door U leven wij, door U sterven wij, en tot U is de opstanding.", "es": "Oh Allah, por Ti hemos llegado a la mañana, por Ti llegamos a la tarde, por Ti vivimos, por Ti morimos y a Ti será la resurrección."]),
            Dhikr(id: "morning-sayyid", arabic: "اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلاَّ أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لاَ يَغْفِرُ الذُّنوبَ إِلاَّ أَنْتَ", ref: "Hisn al-Muslim", times: 1, translations: ["en": "O Allah, You are my Lord. None has the right to be worshipped but You. You created me and I am Your servant, and I keep Your covenant and promise as best I can. I seek refuge in You from the evil of what I have done. I acknowledge Your favour upon me, and I acknowledge my sin, so forgive me, for none forgives sins but You.", "tr": "Allah’ım! Sen benim Rabbimsin. Senden başka ilah yoktur. Beni sen yarattın, ben senin kulunum ve gücüm yettiğince sana verdiğim söz ve ahid üzerindeyim. Yaptığım kötülüklerin şerrinden sana sığınırım. Bana verdiğin nimeti itiraf ediyorum, günahımı da itiraf ediyorum. Beni bağışla; çünkü günahları senden başka bağışlayacak yoktur.", "fr": "Ô Allah, Tu es mon Seigneur. Il n’y a de divinité digne d’adoration que Toi. Tu m’as créé et je suis Ton serviteur, et je reste fidèle à mon engagement envers Toi et à Ta promesse autant que je le peux. Je cherche refuge auprès de Toi contre le mal de ce que j’ai commis. Je reconnais Ton bienfait envers moi et je reconnais mon péché. Pardonne-moi donc, car nul ne pardonne les péchés en dehors de Toi.", "it": "O Allah, Tu sei il mio Signore. Non vi è divinità degna di adorazione all’infuori di Te. Tu mi hai creato e io sono Tuo servo, e rimango fedele al patto con Te e alla Tua promessa per quanto posso. Cerco rifugio in Te dal male di ciò che ho commesso. Riconosco il Tuo favore su di me e riconosco il mio peccato; perdonami dunque, poiché nessuno perdona i peccati se non Tu.", "de": "O Allah, Du bist mein Herr. Es gibt keinen Gott, der anzubeten ist, außer Dir. Du hast mich erschaffen, und ich bin Dein Diener, und ich halte mich an meinen Bund mit Dir und an Dein Versprechen, so gut ich kann. Ich suche Zuflucht bei Dir vor dem Bösen, das ich getan habe. Ich erkenne Deine Gunst an mir an, und ich erkenne meine Sünde an. So vergib mir, denn niemand vergibt die Sünden außer Dir.", "nl": "O Allah, U bent mijn Heer. Er is geen god die het recht heeft aanbeden te worden behalve U. U hebt mij geschapen en ik ben Uw dienaar, en ik houd mij zo goed ik kan aan mijn verbond met U en aan Uw belofte. Ik zoek toevlucht bij U tegen het kwaad dat ik heb begaan. Ik erken Uw gunst aan mij en ik erken mijn zonde. Vergeef mij dus, want niemand vergeeft de zonden behalve U.", "es": "Oh Allah, Tú eres mi Señor. No hay más divinidad digna de adoración que Tú. Me creaste y soy Tu siervo, y mantengo mi compromiso y Tu promesa en la medida de mis posibilidades. Me refugio en Ti del mal que he cometido. Reconozco Tu favor sobre mí y reconozco mi pecado; perdóname, pues nadie perdona los pecados sino Tú."]),
            Dhikr(id: "morning-radeetu", arabic: "رَضِيتُ بِاللَّهِ رَبَّاً، وَبِالْإِسْلاَمِ دِيناً، وَبِمُحَمَّدٍ ﷺ نَبِيّاً", ref: "Hisn al-Muslim", times: 3, translations: ["en": "I am pleased with Allah as my Lord, with Islam as my religion, and with Muhammad (peace be upon him) as my Prophet.", "tr": "Rab olarak Allah’tan, din olarak İslam’dan ve peygamber olarak Muhammed’den (sallallahu aleyhi ve sellem) razı oldum.", "fr": "Je suis satisfait d’Allah comme Seigneur, de l’Islam comme religion et de Muhammad (paix et bénédiction sur lui) comme Prophète.", "it": "Mi accontento di Allah come Signore, dell’Islam come religione e di Muhammad (pace e benedizione su di lui) come Profeta.", "de": "Ich bin zufrieden mit Allah als Herrn, mit dem Islam als Religion und mit Muhammad (Friede und Segen auf ihm) als Propheten.", "nl": "Ik ben tevreden met Allah als Heer, met de islam als godsdienst en met Mohammed (vrede en zegeningen zij met hem) als profeet.", "es": "Estoy conforme con Allah como Señor, con el Islam como religión y con Muhammad (la paz y las bendiciones sean con él) como Profeta."]),
            Dhikr(id: "morning-bismillah", arabic: "بِسْمِ اللَّهِ الَّذِي لاَ يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلاَ فِي السّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ", ref: "Hisn al-Muslim", times: 3, translations: ["en": "In the name of Allah, with whose name nothing on earth or in heaven can cause harm, and He is the All-Hearing, the All-Knowing.", "tr": "Adı ile birlikte yerde ve gökte hiçbir şeyin zarar veremediği Allah’ın adıyla. O, her şeyi işitendir, bilendir.", "fr": "Au nom d’Allah, avec le nom duquel rien sur terre ni dans le ciel ne peut nuire, et Il est l’Audient, l’Omniscient.", "it": "Nel nome di Allah, con il cui nome nulla sulla terra né nel cielo può nuocere, ed Egli è Colui che tutto ascolta, Colui che tutto sa.", "de": "Im Namen Allahs, mit dessen Namen nichts auf der Erde und im Himmel schaden kann, und Er ist der Allhörende, der Allwissende.", "nl": "In de naam van Allah, met wiens naam niets op aarde noch in de hemel schade kan toebrengen, en Hij is de Alhorende, de Alwetende.", "es": "En el nombre de Allah, con cuyo nombre nada en la tierra ni en el cielo puede causar daño, y Él es el Omnioyente, el Omnisciente."]),
            Dhikr(id: "morning-hasbi", arabic: "حَسْبِيَ اللَّهُ لاَ إِلَهَ إِلاَّ هُوَ عَلَيهِ تَوَكَّلتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ", ref: "Hisn al-Muslim", times: 7, translations: ["en": "Allah is sufficient for me. None has the right to be worshipped but Him. In Him I place my trust, and He is the Lord of the Mighty Throne.", "tr": "Allah bana yeter. O’ndan başka ilah yoktur. Yalnız O’na dayandım ve O, yüce Arş’ın Rabbidir.", "fr": "Allah me suffit. Il n’y a de divinité digne d’adoration que Lui. En Lui je place ma confiance, et Il est le Seigneur du Trône immense.", "it": "Allah mi basta. Non vi è divinità degna di adorazione all’infuori di Lui. In Lui ripongo la mia fiducia ed Egli è il Signore del Trono maestoso.", "de": "Allah genügt mir. Es gibt keinen Gott, der anzubeten ist, außer Ihm. Auf Ihn verlasse ich mich, und Er ist der Herr des gewaltigen Throns.", "nl": "Allah is mij genoeg. Er is geen god die het recht heeft aanbeden te worden behalve Hij. Op Hem vertrouw ik en Hij is de Heer van de machtige Troon.", "es": "Allah me basta. No hay más divinidad digna de adoración que Él. En Él pongo mi confianza, y Él es el Señor del Trono inmenso."]),
            Dhikr(id: "morning-subhan", arabic: "سُبْحَانَ اللَّهِ وَبِحَمْدِهِ", ref: "Hisn al-Muslim", times: 100, translations: ["en": "Glory be to Allah and praise be to Him.", "tr": "Allah’ı hamd ile tesbih ederim.", "fr": "Gloire à Allah et louange à Lui.", "it": "Gloria ad Allah e lode a Lui.", "de": "Gepriesen sei Allah, und Ihm gebührt das Lob.", "nl": "Glorie zij Allah en lof zij Hem.", "es": "Gloria a Allah y alabanza a Él."]),
            Dhikr(id: "morning-tahlil", arabic: "لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ", ref: "Hisn al-Muslim", times: 10, translations: ["en": "None has the right to be worshipped but Allah alone, with no partner. His is the dominion and His is the praise, and He is over all things capable.", "tr": "Allah’tan başka ilah yoktur; O tektir, ortağı yoktur. Mülk O’nundur, hamd O’na aittir ve O her şeye kadirdir.", "fr": "Il n’y a de divinité digne d’adoration qu’Allah, l’Unique, sans associé. À Lui la royauté, à Lui la louange, et Il est capable de toute chose.", "it": "Non vi è divinità degna di adorazione all’infuori di Allah, Unico, senza associati. A Lui appartiene il regno, a Lui la lode, ed Egli è onnipotente su ogni cosa.", "de": "Es gibt keinen Gott, der anzubeten ist, außer Allah, dem Einen, der keinen Teilhaber hat. Ihm gehört die Herrschaft, Ihm gebührt das Lob, und Er hat Macht über alle Dinge.", "nl": "Er is geen god die het recht heeft aanbeden te worden behalve Allah, de Enige, zonder deelgenoot. Aan Hem behoort de heerschappij, aan Hem komt de lof toe en Hij heeft macht over alle dingen.", "es": "No hay más divinidad digna de adoración que Allah, Único, sin asociado. Suyo es el dominio y Suya es la alabanza, y Él tiene poder sobre todas las cosas."]),
        ]
        case "evening": return [
            Dhikr(id: "evening-kursi", arabic: "﴿ اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ ﴾", ref: "Quran 2:255 · Al-Baqarah", times: 1, translations: ["en": "Allah! There is no deity save Him, the Alive, the Eternal. Neither slumber nor sleep overtaketh Him. Unto Him belongeth whatsoever is in the heavens and whatsoever is in the earth. Who is he that intercedeth with Him save by His leave? He knoweth that which is in front of them and that which is behind them, while they encompass nothing of His knowledge save what He will. His throne includeth the heavens and the earth, and He is never weary of preserving them. He is the Sublime, the Tremendous", "tr": "Allah, O'ndan başka tanrı olmayan, kendisini uyuklama ve uyku tutmayan, diri, her an yaratıklarını gözetip durandır. Göklerde olan ve yerde olan ancak O'nundur. O'nun izni olmadan katında şefaat edecek kimdir? Onların işlediklerini ve işleyeceklerini bilir, dilediğinden başka ilminden hiçbir şeyi kavrayamazlar. Hükümranlığı gökleri ve yeri kaplamıştır, onların gözetilmesi O'na ağır gelmez. O yücedir, büyüktür", "fr": "Allah! Point de divinité à part Lui, le Vivant, Celui qui subsiste par lui-même «Al-Qayyûm». Ni somnolence ni sommeil ne Le saisissent. A Lui appartient tout ce qui est dans les cieux et sur la terre. Qui peut intercéder auprès de Lui sans Sa permission? Il connaît leur passé et leur futur. Et, de Sa science, ils n'embrassent que ce qu'Il veut. Son Trône «Kursiy», déborde les cieux et la terre, dont la garde ne Lui coûte aucune peine. Et Il est le Très Haut, le Très Grand", "it": "Allah! Non c'è altro dio che Lui, il Vivente, l'Assoluto. Non Lo prendon mai sopore, né sonno. A Lui appartiene tutto quello che è nei cieli e sulla terra. Chi può intercedere presso di Lui senza il Suo permesso? Egli conosce quello che è davanti a loro e quello che è dietro di loro e, della Sua scienza, essi apprendono solo ciò che Egli vuole. Il Suo Trono è più vasto dei cieli e della terra, e custodirli non Gli costa sforzo alcuno. Egli è l'Altissimo, l'Immenso", "de": "Allah - es gibt keinen Gott außer Ihm, dem Lebendigen und Beständigen. Ihn überkommt weder Schlummer noch Schlaf. Ihm gehört (alles), was in den Himmeln und was auf der Erde ist. Wer ist es denn, der bei Ihm Fürsprache einlegen könnte - außer mit Seiner Erlaubnis? Er weiß, was vor ihnen und was hinter ihnen liegt, sie aber umfassen nichts von Seinem Wissen - außer, was Er will. Sein Thronschemel umfaßt die Himmel und die Erde, und ihre Behütung beschwert Ihn nicht. Er ist der Erhabene und Allgewaltige", "nl": "Allah, er is geen god dan Hij, de Levende, de Zelfstandige, sluimer noch slaap kan Hem treffen, aan Hem behoort toe wat er in de hemelen en wat er op de aarde is. Wie is degene die van voorspraak is bij Hem zonder Zijn verlof? Hij kent wat er voor hen is en wat er achter hen is. En zij kunnen niets van Zijn Kennis omvatten, behalve wat Hij wil. En Zijn Zetel strekt zich uit over de Hemelen en de Aarde en het waken over beide vermoeit Hem niet. En Hij is de Verhevene, de Almachtige", "es": "¡Alá! No hay más dios que El. el Viviente, el Subsistente. Ni la somnolencia ni el sueño se apoderan de Él. Suyo es lo que está en los cielos y en la tierra. ¿Quién podrá interceder ante Él si no es con Su permiso? Conoce su pasado y su futuro, mientras que ellos no abarcan nada de Su ciencia, excepto lo que Él quiere. Su Trono se extiende sobre los cielos y sobre la tierra y su conservación no le resulta onerosa. Él es el Altísimo, el Grandioso"]),
            Dhikr(id: "evening-ikh", arabic: "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ\nقُلْ هُوَ اللَّهُ أَحَدٌ ﴿١﴾\nاللَّهُ الصَّمَدُ ﴿٢﴾\nلَمْ يَلِدْ وَلَمْ يُولَدْ ﴿٣﴾\nوَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ ﴿٤﴾", ref: "Quran 112 · Al-Ikhlas", times: 3, translations: ["en": "1. Say: He is Allah, the One\n2. Allah, the eternally Besought of all\n3. He begetteth not nor was begotten\n4. And there is none comparable unto Him", "tr": "1. De ki: O Allah bir tektir\n2. Allah her şeyden müstağni ve her şey O'na muhtaçtır\n3. O doğurmamış ve doğmamıştır\n4. Hiçbir şey O'na denk değildir", "fr": "1. Dis: «Il est Allah, Unique\n2. Allah, Le Seul à être imploré pour ce que nous désirons\n3. Il n'a jamais engendré, n'a pas été engendré non plus\n4. Et nul n'est égal à Lui»", "it": "1. Di’: “Egli Allah è Unico\n2. Allah è l’Assoluto\n3. Non ha generato, non è stato generato\n4. e nessuno è eguale a Lui”", "de": "1. Sag: Er ist Allah, ein Einer\n2. Allah, der Überlegene\n3. Er hat nicht gezeugt und ist nicht gezeugt worden\n4. und niemand ist Ihm jemals gleich", "nl": "1. Zeg: \"Hij is Allah, de Enige\n2. Allah is de Enige van Wie al het geschapene afhankelijk is\n3. Hij heeft niet verwekt en is niet verwekt\n4. En niet één is aan Hem gelijkwaardig", "es": "1. Di: «¡Él es Alá, Uno\n2. Dios, el Eterno\n3. No ha engendrado, ni ha sido engendrado\n4. No tiene par»"]),
            Dhikr(id: "evening-fal", arabic: "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ\nقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ﴿١﴾\nمِنْ شَرِّ مَا خَلَقَ ﴿٢﴾\nوَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ﴿٣﴾\nوَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ﴿٤﴾\nوَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ ﴿٥﴾", ref: "Quran 113 · Al-Falaq", times: 3, translations: ["en": "1. Say: I seek refuge in the Lord of the Daybreak\n2. From the evil of that which He created\n3. From the evil of the darkness when it is intense\n4. And from the evil of malignant witchcraft\n5. And from the evil of the envier when he envieth", "tr": "De ki: \"Yaratıkların şerrinden, bastırdığı zaman karanlığın şerrinden, düğümlere nefes eden büyücülerin şerrinden, hased ettiği zaman hasedcilerin şerrinden, tan yerini ağartan Rabbe sığınırım", "fr": "1. Dis: «Je cherche protection auprès du Seigneur de l'aube naissante\n2. contre le mal des êtres qu'Il a créés\n3. contre le mal de l'obscurité quand elle s'approfondit\n4. contre le mal de celles qui soufflent [les sorcières] sur les nœuds\n5. et contre le mal de l'envieux quand il envie»", "it": "1. Di’: “Mi rifugio nel Signore dell’alba nascente\n2. contro il male che ha creato\n3. e contro il male dell’oscurità che si estende\n4. e contro il male delle soffianti sui nodi\n5. e contro il male dell’invidioso quando invidia”", "de": "1. Sag: Ich nehme Zuflucht beim Herrn des Tagesanbruchs\n2. vor dem Übel dessen, was Er erschaffen hat\n3. und vor dem Übel der Dunkelheit, wenn sie zunimmt\n4. und vor dem Übel der Knotenanbläserinnen\n5. und vor dem Übel eines (jeden) Neidenden, wenn er neidet", "nl": "1. Zeg: \"Ik zoek bescherming bij de Heer der dageraad\n2. Tegen het kwaad dat Hij geschapen heeft\n3. En tegen het kwaad van de donkere nacht wanneer hij aanbreekt\n4. En tegen het kwaad van hen die op knopen blazen\n5. En tegen het kwaad van een jaloerse wanneer deze jaloers is", "es": "1. Di: «Me refugio en el Señor del alba\n2. del mal que hacen sus criaturas\n3. del mal de la oscuridad cuando se extiende\n4. del mal de las que soplan en los nudos\n5. del mal envidioso cuando envidia»"]),
            Dhikr(id: "evening-nas", arabic: "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ\nقُلْ أَعُوذُ بِرَبِّ النَّاسِ ﴿١﴾\nمَلِكِ النَّاسِ ﴿٢﴾\nإِلَٰهِ النَّاسِ ﴿٣﴾\nمِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ﴿٤﴾\nالَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ﴿٥﴾\nمِنَ الْجِنَّةِ وَالنَّاسِ ﴿٦﴾", ref: "Quran 114 · An-Nas", times: 3, translations: ["en": "1. Say: I seek refuge in the Lord of mankind\n2. The King of mankind\n3. The god of mankind\n4. From the evil of the sneaking whisperer\n5. Who whispereth in the hearts of mankind\n6. Of the jinn and of mankind", "tr": "De ki: \"İnsanlardan ve cinlerden ve insanların gönüllerine vesvese veren o sinsi vesvesecinin şerrinden, insanların Tanrısı, insanların Hükümranı ve insanların Rabbi olan Allah'a sığınırım", "fr": "1. Dis: «Je cherche protection auprès du Seigneur des hommes\n2. Le Souverain des hommes\n3. Dieu des hommes\n4. contre le mal du mauvais conseiller, furtif\n5. qui souffle le mal dans les poitrines des hommes\n6. qu'il (le conseiller) soit un djinn, ou un être humain»", "it": "1. Di’: “Mi rifugio nel Signore degli uomini\n2. Re degli uomini\n3. Dio degli uomini\n4. contro il male del sussurratore furtivo\n5. che soffia il male nei cuori degli uomini\n6. che [venga] dai dèmoni o dagli uomini”", "de": "1. Sag: Ich nehme Zuflucht beim Herrn der Menschen\n2. dem König der Menschen\n3. dem Gott der Menschen\n4. vor dem Übel des Einflüsterers, des Davonschleichers\n5. der in die Brüste der Menschen einflüstert\n6. von den Ginn und den Menschen", "nl": "1. Zeg: \"Ik zoek bescherming bij de Heer van de mensen\n2. De Koning van de mensen\n3. De God van de mensen\n4. Tegen het kwaad van de wegsluipende influisteraar\n5. Degene die in de harten van de mensen influistert\n6. Van de Djinn's en de mensen", "es": "1. Di: «Me refugio en el Señor de los hombres\n2. el Rey de los hombres\n3. el Dios de los hombres\n4. del mal de la insinuación, del que se escabulle\n5. que insinúa en el ánimo de los hombres\n6. sea genio, sea hombre»"]),
            Dhikr(id: "evening-amsayna", arabic: "أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لاَ إِلَهَ إلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذِهِ اللَّيْلَةِ وَخَيْرَ مَا بَعْدَهَا، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذِهِ اللَّيْلَةِ وَشَرِّ مَا بَعْدَهَا، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ", ref: "Hisn al-Muslim", times: 1, translations: ["en": "We have reached the evening and the dominion belongs to Allah. Praise is for Allah. None has the right to be worshipped but Allah alone, with no partner. His is the dominion and His is the praise, and He is over all things capable. My Lord, I ask You for the good of this night and the good of what follows it, and I seek refuge in You from the evil of this night and the evil of what follows it. My Lord, I seek refuge in You from laziness and the evil of old age. My Lord, I seek refuge in You from punishment in the Fire and punishment in the grave.", "tr": "Akşama erdik, mülk de Allah’ın olarak akşama erdi. Hamd Allah’a mahsustur. Allah’tan başka ilah yoktur; O tektir, ortağı yoktur. Mülk O’nundur, hamd O’na aittir ve O her şeye kadirdir. Rabbim! Senden bu gecenin hayrını ve bundan sonrasının hayrını isterim; bu gecenin şerrinden ve bundan sonrasının şerrinden sana sığınırım. Rabbim! Tembellikten ve yaşlılığın kötülüğünden sana sığınırım. Rabbim! Cehennemdeki azaptan ve kabirdeki azaptan sana sığınırım.", "fr": "Nous voici au soir et la royauté appartient à Allah. Louange à Allah. Il n’y a de divinité digne d’adoration qu’Allah, l’Unique, sans associé. À Lui la royauté, à Lui la louange, et Il est capable de toute chose. Seigneur, je Te demande le bien de cette nuit et le bien de ce qui la suit, et je cherche refuge auprès de Toi contre le mal de cette nuit et le mal de ce qui la suit. Seigneur, je cherche refuge auprès de Toi contre la paresse et les maux de la vieillesse. Seigneur, je cherche refuge auprès de Toi contre le châtiment du Feu et le châtiment de la tombe.", "it": "Siamo giunti alla sera e il regno appartiene ad Allah. La lode è per Allah. Non vi è divinità degna di adorazione all’infuori di Allah, Unico, senza associati. A Lui appartiene il regno, a Lui la lode, ed Egli è onnipotente su ogni cosa. Mio Signore, Ti chiedo il bene di questa notte e il bene di ciò che la segue, e cerco rifugio in Te dal male di questa notte e dal male di ciò che la segue. Mio Signore, cerco rifugio in Te dalla pigrizia e dai mali della vecchiaia. Mio Signore, cerco rifugio in Te dal castigo del Fuoco e dal castigo della tomba.", "de": "Wir sind in den Abend gelangt, und die Herrschaft gehört Allah. Lob gebührt Allah. Es gibt keinen Gott, der anzubeten ist, außer Allah, dem Einen, der keinen Teilhaber hat. Ihm gehört die Herrschaft, Ihm gebührt das Lob, und Er hat Macht über alle Dinge. Mein Herr, ich bitte Dich um das Gute dieser Nacht und das Gute dessen, was danach kommt, und ich suche Zuflucht bei Dir vor dem Bösen dieser Nacht und dem Bösen dessen, was danach kommt. Mein Herr, ich suche Zuflucht bei Dir vor Faulheit und den Übeln des Alters. Mein Herr, ich suche Zuflucht bei Dir vor der Strafe im Feuer und der Strafe im Grab.", "nl": "Wij zijn aan de avond toegekomen en de heerschappij behoort aan Allah toe. Lof zij Allah. Er is geen god die het recht heeft aanbeden te worden behalve Allah, de Enige, zonder deelgenoot. Aan Hem behoort de heerschappij, aan Hem komt de lof toe en Hij heeft macht over alle dingen. Mijn Heer, ik vraag U om het goede van deze nacht en het goede van wat erop volgt, en ik zoek toevlucht bij U tegen het kwade van deze nacht en het kwade van wat erop volgt. Mijn Heer, ik zoek toevlucht bij U tegen luiheid en de kwalen van de ouderdom. Mijn Heer, ik zoek toevlucht bij U tegen de straf in het Vuur en de straf in het graf.", "es": "Hemos llegado a la tarde y el dominio pertenece a Allah. La alabanza es para Allah. No hay más divinidad digna de adoración que Allah, Único, sin asociado. Suyo es el dominio y Suya es la alabanza, y Él tiene poder sobre todas las cosas. Señor mío, Te pido el bien de esta noche y el bien de lo que viene después, y me refugio en Ti del mal de esta noche y del mal de lo que viene después. Señor mío, me refugio en Ti de la pereza y de los males de la vejez. Señor mío, me refugio en Ti del castigo del Fuego y del castigo de la tumba."]),
            Dhikr(id: "evening-bika", arabic: "اللَّهُمَّ بِكَ أَمْسَيْنَا، وَبِكَ أَصْبَحْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ وَإِلَيْكَ الْمَصِيرُ", ref: "Hisn al-Muslim", times: 1, translations: ["en": "O Allah, by You we have reached the evening, by You we reach the morning, by You we live, by You we die, and to You is the final return.", "tr": "Allah’ım! Seninle akşama erdik, seninle sabaha ereriz; seninle yaşar, seninle ölürüz ve dönüş sanadır.", "fr": "Ô Allah, c’est par Toi que nous atteignons le soir, par Toi que nous atteignons le matin, par Toi que nous vivons, par Toi que nous mourons, et c’est vers Toi que sera le retour final.", "it": "O Allah, grazie a Te siamo giunti alla sera, grazie a Te giungiamo al mattino, grazie a Te viviamo e grazie a Te moriamo, e a Te sarà il ritorno finale.", "de": "O Allah, durch Dich sind wir in den Abend gelangt, durch Dich gelangen wir in den Morgen, durch Dich leben wir, durch Dich sterben wir, und zu Dir ist die endgültige Rückkehr.", "nl": "O Allah, door U zijn wij aan de avond toegekomen, door U komen wij aan de ochtend toe, door U leven wij, door U sterven wij, en tot U is de uiteindelijke terugkeer.", "es": "Oh Allah, por Ti hemos llegado a la tarde, por Ti llegamos a la mañana, por Ti vivimos, por Ti morimos y a Ti será el retorno final."]),
            Dhikr(id: "evening-sayyid", arabic: "اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلاَّ أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لاَ يَغْفِرُ الذُّنوبَ إِلاَّ أَنْتَ", ref: "Hisn al-Muslim", times: 1, translations: ["en": "O Allah, You are my Lord. None has the right to be worshipped but You. You created me and I am Your servant, and I keep Your covenant and promise as best I can. I seek refuge in You from the evil of what I have done. I acknowledge Your favour upon me, and I acknowledge my sin, so forgive me, for none forgives sins but You.", "tr": "Allah’ım! Sen benim Rabbimsin. Senden başka ilah yoktur. Beni sen yarattın, ben senin kulunum ve gücüm yettiğince sana verdiğim söz ve ahid üzerindeyim. Yaptığım kötülüklerin şerrinden sana sığınırım. Bana verdiğin nimeti itiraf ediyorum, günahımı da itiraf ediyorum. Beni bağışla; çünkü günahları senden başka bağışlayacak yoktur.", "fr": "Ô Allah, Tu es mon Seigneur. Il n’y a de divinité digne d’adoration que Toi. Tu m’as créé et je suis Ton serviteur, et je reste fidèle à mon engagement envers Toi et à Ta promesse autant que je le peux. Je cherche refuge auprès de Toi contre le mal de ce que j’ai commis. Je reconnais Ton bienfait envers moi et je reconnais mon péché. Pardonne-moi donc, car nul ne pardonne les péchés en dehors de Toi.", "it": "O Allah, Tu sei il mio Signore. Non vi è divinità degna di adorazione all’infuori di Te. Tu mi hai creato e io sono Tuo servo, e rimango fedele al patto con Te e alla Tua promessa per quanto posso. Cerco rifugio in Te dal male di ciò che ho commesso. Riconosco il Tuo favore su di me e riconosco il mio peccato; perdonami dunque, poiché nessuno perdona i peccati se non Tu.", "de": "O Allah, Du bist mein Herr. Es gibt keinen Gott, der anzubeten ist, außer Dir. Du hast mich erschaffen, und ich bin Dein Diener, und ich halte mich an meinen Bund mit Dir und an Dein Versprechen, so gut ich kann. Ich suche Zuflucht bei Dir vor dem Bösen, das ich getan habe. Ich erkenne Deine Gunst an mir an, und ich erkenne meine Sünde an. So vergib mir, denn niemand vergibt die Sünden außer Dir.", "nl": "O Allah, U bent mijn Heer. Er is geen god die het recht heeft aanbeden te worden behalve U. U hebt mij geschapen en ik ben Uw dienaar, en ik houd mij zo goed ik kan aan mijn verbond met U en aan Uw belofte. Ik zoek toevlucht bij U tegen het kwaad dat ik heb begaan. Ik erken Uw gunst aan mij en ik erken mijn zonde. Vergeef mij dus, want niemand vergeeft de zonden behalve U.", "es": "Oh Allah, Tú eres mi Señor. No hay más divinidad digna de adoración que Tú. Me creaste y soy Tu siervo, y mantengo mi compromiso y Tu promesa en la medida de mis posibilidades. Me refugio en Ti del mal que he cometido. Reconozco Tu favor sobre mí y reconozco mi pecado; perdóname, pues nadie perdona los pecados sino Tú."]),
            Dhikr(id: "evening-radeetu", arabic: "رَضِيتُ بِاللَّهِ رَبَّاً، وَبِالْإِسْلاَمِ دِيناً، وَبِمُحَمَّدٍ ﷺ نَبِيّاً", ref: "Hisn al-Muslim", times: 3, translations: ["en": "I am pleased with Allah as my Lord, with Islam as my religion, and with Muhammad (peace be upon him) as my Prophet.", "tr": "Rab olarak Allah’tan, din olarak İslam’dan ve peygamber olarak Muhammed’den (sallallahu aleyhi ve sellem) razı oldum.", "fr": "Je suis satisfait d’Allah comme Seigneur, de l’Islam comme religion et de Muhammad (paix et bénédiction sur lui) comme Prophète.", "it": "Mi accontento di Allah come Signore, dell’Islam come religione e di Muhammad (pace e benedizione su di lui) come Profeta.", "de": "Ich bin zufrieden mit Allah als Herrn, mit dem Islam als Religion und mit Muhammad (Friede und Segen auf ihm) als Propheten.", "nl": "Ik ben tevreden met Allah als Heer, met de islam als godsdienst en met Mohammed (vrede en zegeningen zij met hem) als profeet.", "es": "Estoy conforme con Allah como Señor, con el Islam como religión y con Muhammad (la paz y las bendiciones sean con él) como Profeta."]),
            Dhikr(id: "evening-bismillah", arabic: "بِسْمِ اللَّهِ الَّذِي لاَ يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلاَ فِي السّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ", ref: "Hisn al-Muslim", times: 3, translations: ["en": "In the name of Allah, with whose name nothing on earth or in heaven can cause harm, and He is the All-Hearing, the All-Knowing.", "tr": "Adı ile birlikte yerde ve gökte hiçbir şeyin zarar veremediği Allah’ın adıyla. O, her şeyi işitendir, bilendir.", "fr": "Au nom d’Allah, avec le nom duquel rien sur terre ni dans le ciel ne peut nuire, et Il est l’Audient, l’Omniscient.", "it": "Nel nome di Allah, con il cui nome nulla sulla terra né nel cielo può nuocere, ed Egli è Colui che tutto ascolta, Colui che tutto sa.", "de": "Im Namen Allahs, mit dessen Namen nichts auf der Erde und im Himmel schaden kann, und Er ist der Allhörende, der Allwissende.", "nl": "In de naam van Allah, met wiens naam niets op aarde noch in de hemel schade kan toebrengen, en Hij is de Alhorende, de Alwetende.", "es": "En el nombre de Allah, con cuyo nombre nada en la tierra ni en el cielo puede causar daño, y Él es el Omnioyente, el Omnisciente."]),
            Dhikr(id: "evening-hasbi", arabic: "حَسْبِيَ اللَّهُ لاَ إِلَهَ إِلاَّ هُوَ عَلَيهِ تَوَكَّلتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ", ref: "Hisn al-Muslim", times: 7, translations: ["en": "Allah is sufficient for me. None has the right to be worshipped but Him. In Him I place my trust, and He is the Lord of the Mighty Throne.", "tr": "Allah bana yeter. O’ndan başka ilah yoktur. Yalnız O’na dayandım ve O, yüce Arş’ın Rabbidir.", "fr": "Allah me suffit. Il n’y a de divinité digne d’adoration que Lui. En Lui je place ma confiance, et Il est le Seigneur du Trône immense.", "it": "Allah mi basta. Non vi è divinità degna di adorazione all’infuori di Lui. In Lui ripongo la mia fiducia ed Egli è il Signore del Trono maestoso.", "de": "Allah genügt mir. Es gibt keinen Gott, der anzubeten ist, außer Ihm. Auf Ihn verlasse ich mich, und Er ist der Herr des gewaltigen Throns.", "nl": "Allah is mij genoeg. Er is geen god die het recht heeft aanbeden te worden behalve Hij. Op Hem vertrouw ik en Hij is de Heer van de machtige Troon.", "es": "Allah me basta. No hay más divinidad digna de adoración que Él. En Él pongo mi confianza, y Él es el Señor del Trono inmenso."]),
            Dhikr(id: "evening-kalimat", arabic: "أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ", ref: "Hisn al-Muslim", times: 3, translations: ["en": "I seek refuge in the perfect words of Allah from the evil of what He has created.", "tr": "Allah’ın eksiksiz kelimelerine sığınırım, yarattığı şeylerin şerrinden.", "fr": "Je cherche refuge dans les paroles parfaites d’Allah contre le mal de ce qu’Il a créé.", "it": "Cerco rifugio nelle parole perfette di Allah dal male di ciò che Egli ha creato.", "de": "Ich suche Zuflucht bei den vollkommenen Worten Allahs vor dem Bösen dessen, was Er erschaffen hat.", "nl": "Ik zoek toevlucht bij de volmaakte woorden van Allah tegen het kwaad van wat Hij heeft geschapen.", "es": "Me refugio en las palabras perfectas de Allah del mal de lo que Él ha creado."]),
            Dhikr(id: "evening-subhan", arabic: "سُبْحَانَ اللَّهِ وَبِحَمْدِهِ", ref: "Hisn al-Muslim", times: 100, translations: ["en": "Glory be to Allah and praise be to Him.", "tr": "Allah’ı hamd ile tesbih ederim.", "fr": "Gloire à Allah et louange à Lui.", "it": "Gloria ad Allah e lode a Lui.", "de": "Gepriesen sei Allah, und Ihm gebührt das Lob.", "nl": "Glorie zij Allah en lof zij Hem.", "es": "Gloria a Allah y alabanza a Él."]),
            Dhikr(id: "evening-tahlil", arabic: "لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ", ref: "Hisn al-Muslim", times: 10, translations: ["en": "None has the right to be worshipped but Allah alone, with no partner. His is the dominion and His is the praise, and He is over all things capable.", "tr": "Allah’tan başka ilah yoktur; O tektir, ortağı yoktur. Mülk O’nundur, hamd O’na aittir ve O her şeye kadirdir.", "fr": "Il n’y a de divinité digne d’adoration qu’Allah, l’Unique, sans associé. À Lui la royauté, à Lui la louange, et Il est capable de toute chose.", "it": "Non vi è divinità degna di adorazione all’infuori di Allah, Unico, senza associati. A Lui appartiene il regno, a Lui la lode, ed Egli è onnipotente su ogni cosa.", "de": "Es gibt keinen Gott, der anzubeten ist, außer Allah, dem Einen, der keinen Teilhaber hat. Ihm gehört die Herrschaft, Ihm gebührt das Lob, und Er hat Macht über alle Dinge.", "nl": "Er is geen god die het recht heeft aanbeden te worden behalve Allah, de Enige, zonder deelgenoot. Aan Hem behoort de heerschappij, aan Hem komt de lof toe en Hij heeft macht over alle dingen.", "es": "No hay más divinidad digna de adoración que Allah, Único, sin asociado. Suyo es el dominio y Suya es la alabanza, y Él tiene poder sobre todas las cosas."]),
        ]
        case "afterPrayer": return [
            Dhikr(id: "afterPrayer-istighfar", arabic: "أَسْتَغْفِرُ اللَّهَ", ref: "Hisn al-Muslim", times: 3, translations: ["en": "I seek forgiveness from Allah.", "tr": "Allah’tan bağışlanma dilerim.", "fr": "Je demande pardon à Allah.", "it": "Chiedo perdono ad Allah.", "de": "Ich bitte Allah um Vergebung.", "nl": "Ik vraag Allah om vergeving.", "es": "Pido perdón a Allah."]),
            Dhikr(id: "afterPrayer-salam", arabic: "اللَّهُمَّ أَنْتَ السَّلاَمُ، وَمِنْكَ السَّلاَمُ، تَبَارَكْتَ يَا ذَا الْجَلاَلِ وَالْإِكْرَامِ", ref: "Hisn al-Muslim", times: 1, translations: ["en": "O Allah, You are Peace and from You comes peace. Blessed are You, O Possessor of majesty and honour.", "tr": "Allah’ım! Sen selamsın, selam sendendir. Ey celal ve ikram sahibi, sen ne yücesin!", "fr": "Ô Allah, Tu es la Paix et la paix vient de Toi. Béni sois-Tu, ô Détenteur de la majesté et de la générosité.", "it": "O Allah, Tu sei la Pace e da Te viene la pace. Benedetto sei Tu, o Possessore della maestà e della generosità.", "de": "O Allah, Du bist der Friede, und von Dir kommt der Friede. Gesegnet seist Du, o Herr der Majestät und der Ehre.", "nl": "O Allah, U bent de Vrede en van U komt de vrede. Gezegend bent U, o Bezitter van majesteit en eer.", "es": "Oh Allah, Tú eres la Paz y de Ti viene la paz. Bendito seas, oh Poseedor de majestad y generosidad."]),
            Dhikr(id: "afterPrayer-tahlil3", arabic: "لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ", ref: "Hisn al-Muslim", times: 3, translations: ["en": "None has the right to be worshipped but Allah alone, with no partner. His is the dominion and His is the praise, and He is over all things capable.", "tr": "Allah’tan başka ilah yoktur; O tektir, ortağı yoktur. Mülk O’nundur, hamd O’na aittir ve O her şeye kadirdir.", "fr": "Il n’y a de divinité digne d’adoration qu’Allah, l’Unique, sans associé. À Lui la royauté, à Lui la louange, et Il est capable de toute chose.", "it": "Non vi è divinità degna di adorazione all’infuori di Allah, Unico, senza associati. A Lui appartiene il regno, a Lui la lode, ed Egli è onnipotente su ogni cosa.", "de": "Es gibt keinen Gott, der anzubeten ist, außer Allah, dem Einen, der keinen Teilhaber hat. Ihm gehört die Herrschaft, Ihm gebührt das Lob, und Er hat Macht über alle Dinge.", "nl": "Er is geen god die het recht heeft aanbeden te worden behalve Allah, de Enige, zonder deelgenoot. Aan Hem behoort de heerschappij, aan Hem komt de lof toe en Hij heeft macht over alle dingen.", "es": "No hay más divinidad digna de adoración que Allah, Único, sin asociado. Suyo es el dominio y Suya es la alabanza, y Él tiene poder sobre todas las cosas."]),
            Dhikr(id: "afterPrayer-mani", arabic: "اللَّهُمَّ لاَ مَانِعَ لِمَا أَعْطَيْتَ، وَلاَ مُعْطِيَ لِمَا مَنَعْتَ، وَلاَ يَنْفَعُ ذَا الْجَدِّ مِنْكَ الجَدُّ", ref: "Hisn al-Muslim", times: 1, translations: ["en": "O Allah, none can withhold what You give, none can give what You withhold, and the might of the mighty cannot benefit anyone against You.", "tr": "Allah’ım! Senin verdiğine engel olacak, engellediğini verecek yoktur. Zenginlik ve güç sahibine, senin katında zenginliği ve gücü fayda vermez.", "fr": "Ô Allah, nul ne peut empêcher ce que Tu accordes, nul ne peut donner ce que Tu refuses, et la puissance du puissant ne lui sert à rien face à Toi.", "it": "O Allah, nessuno può impedire ciò che Tu concedi, nessuno può dare ciò che Tu neghi, e la potenza del potente non giova a nessuno contro di Te.", "de": "O Allah, niemand kann verwehren, was Du gibst, und niemand kann geben, was Du verwehrst, und die Macht des Mächtigen nützt vor Dir nichts.", "nl": "O Allah, niemand kan tegenhouden wat U geeft en niemand kan geven wat U onthoudt, en de macht van de machtige baat niemand tegenover U.", "es": "Oh Allah, nadie puede impedir lo que Tú concedes, ni nadie puede dar lo que Tú niegas, y el poder del poderoso no le beneficia frente a Ti."]),
            Dhikr(id: "afterPrayer-subhanallah", arabic: "سُبْحَانَ اللَّهِ", ref: "Hisn al-Muslim", times: 33, translations: ["en": "Glory be to Allah.", "tr": "Allah’ı tesbih ederim.", "fr": "Gloire à Allah.", "it": "Gloria ad Allah.", "de": "Gepriesen sei Allah.", "nl": "Glorie zij Allah.", "es": "Gloria a Allah."]),
            Dhikr(id: "afterPrayer-alhamdulillah", arabic: "الْحَمْدُ لِلَّهِ", ref: "Hisn al-Muslim", times: 33, translations: ["en": "All praise is for Allah.", "tr": "Hamd Allah’a mahsustur.", "fr": "Louange à Allah.", "it": "La lode è per Allah.", "de": "Alles Lob gebührt Allah.", "nl": "Alle lof zij Allah.", "es": "La alabanza es para Allah."]),
            Dhikr(id: "afterPrayer-akbar", arabic: "اللَّهُ أَكْبَرُ", ref: "Hisn al-Muslim", times: 33, translations: ["en": "Allah is the Greatest.", "tr": "Allah en büyüktür.", "fr": "Allah est le Plus Grand.", "it": "Allah è il più grande.", "de": "Allah ist der Größte.", "nl": "Allah is de Grootste.", "es": "Allah es el más grande."]),
            Dhikr(id: "afterPrayer-tahlil", arabic: "لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ", ref: "Hisn al-Muslim", times: 1, translations: ["en": "None has the right to be worshipped but Allah alone, with no partner. His is the dominion and His is the praise, and He is over all things capable.", "tr": "Allah’tan başka ilah yoktur; O tektir, ortağı yoktur. Mülk O’nundur, hamd O’na aittir ve O her şeye kadirdir.", "fr": "Il n’y a de divinité digne d’adoration qu’Allah, l’Unique, sans associé. À Lui la royauté, à Lui la louange, et Il est capable de toute chose.", "it": "Non vi è divinità degna di adorazione all’infuori di Allah, Unico, senza associati. A Lui appartiene il regno, a Lui la lode, ed Egli è onnipotente su ogni cosa.", "de": "Es gibt keinen Gott, der anzubeten ist, außer Allah, dem Einen, der keinen Teilhaber hat. Ihm gehört die Herrschaft, Ihm gebührt das Lob, und Er hat Macht über alle Dinge.", "nl": "Er is geen god die het recht heeft aanbeden te worden behalve Allah, de Enige, zonder deelgenoot. Aan Hem behoort de heerschappij, aan Hem komt de lof toe en Hij heeft macht over alle dingen.", "es": "No hay más divinidad digna de adoración que Allah, Único, sin asociado. Suyo es el dominio y Suya es la alabanza, y Él tiene poder sobre todas las cosas."]),
            Dhikr(id: "afterPrayer-kursi", arabic: "﴿ اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ ﴾", ref: "Quran 2:255 · Al-Baqarah", times: 1, translations: ["en": "Allah! There is no deity save Him, the Alive, the Eternal. Neither slumber nor sleep overtaketh Him. Unto Him belongeth whatsoever is in the heavens and whatsoever is in the earth. Who is he that intercedeth with Him save by His leave? He knoweth that which is in front of them and that which is behind them, while they encompass nothing of His knowledge save what He will. His throne includeth the heavens and the earth, and He is never weary of preserving them. He is the Sublime, the Tremendous", "tr": "Allah, O'ndan başka tanrı olmayan, kendisini uyuklama ve uyku tutmayan, diri, her an yaratıklarını gözetip durandır. Göklerde olan ve yerde olan ancak O'nundur. O'nun izni olmadan katında şefaat edecek kimdir? Onların işlediklerini ve işleyeceklerini bilir, dilediğinden başka ilminden hiçbir şeyi kavrayamazlar. Hükümranlığı gökleri ve yeri kaplamıştır, onların gözetilmesi O'na ağır gelmez. O yücedir, büyüktür", "fr": "Allah! Point de divinité à part Lui, le Vivant, Celui qui subsiste par lui-même «Al-Qayyûm». Ni somnolence ni sommeil ne Le saisissent. A Lui appartient tout ce qui est dans les cieux et sur la terre. Qui peut intercéder auprès de Lui sans Sa permission? Il connaît leur passé et leur futur. Et, de Sa science, ils n'embrassent que ce qu'Il veut. Son Trône «Kursiy», déborde les cieux et la terre, dont la garde ne Lui coûte aucune peine. Et Il est le Très Haut, le Très Grand", "it": "Allah! Non c'è altro dio che Lui, il Vivente, l'Assoluto. Non Lo prendon mai sopore, né sonno. A Lui appartiene tutto quello che è nei cieli e sulla terra. Chi può intercedere presso di Lui senza il Suo permesso? Egli conosce quello che è davanti a loro e quello che è dietro di loro e, della Sua scienza, essi apprendono solo ciò che Egli vuole. Il Suo Trono è più vasto dei cieli e della terra, e custodirli non Gli costa sforzo alcuno. Egli è l'Altissimo, l'Immenso", "de": "Allah - es gibt keinen Gott außer Ihm, dem Lebendigen und Beständigen. Ihn überkommt weder Schlummer noch Schlaf. Ihm gehört (alles), was in den Himmeln und was auf der Erde ist. Wer ist es denn, der bei Ihm Fürsprache einlegen könnte - außer mit Seiner Erlaubnis? Er weiß, was vor ihnen und was hinter ihnen liegt, sie aber umfassen nichts von Seinem Wissen - außer, was Er will. Sein Thronschemel umfaßt die Himmel und die Erde, und ihre Behütung beschwert Ihn nicht. Er ist der Erhabene und Allgewaltige", "nl": "Allah, er is geen god dan Hij, de Levende, de Zelfstandige, sluimer noch slaap kan Hem treffen, aan Hem behoort toe wat er in de hemelen en wat er op de aarde is. Wie is degene die van voorspraak is bij Hem zonder Zijn verlof? Hij kent wat er voor hen is en wat er achter hen is. En zij kunnen niets van Zijn Kennis omvatten, behalve wat Hij wil. En Zijn Zetel strekt zich uit over de Hemelen en de Aarde en het waken over beide vermoeit Hem niet. En Hij is de Verhevene, de Almachtige", "es": "¡Alá! No hay más dios que El. el Viviente, el Subsistente. Ni la somnolencia ni el sueño se apoderan de Él. Suyo es lo que está en los cielos y en la tierra. ¿Quién podrá interceder ante Él si no es con Su permiso? Conoce su pasado y su futuro, mientras que ellos no abarcan nada de Su ciencia, excepto lo que Él quiere. Su Trono se extiende sobre los cielos y sobre la tierra y su conservación no le resulta onerosa. Él es el Altísimo, el Grandioso"]),
            Dhikr(id: "afterPrayer-ikh", arabic: "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ\nقُلْ هُوَ اللَّهُ أَحَدٌ ﴿١﴾\nاللَّهُ الصَّمَدُ ﴿٢﴾\nلَمْ يَلِدْ وَلَمْ يُولَدْ ﴿٣﴾\nوَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ ﴿٤﴾", ref: "Quran 112 · Al-Ikhlas", times: 1, translations: ["en": "1. Say: He is Allah, the One\n2. Allah, the eternally Besought of all\n3. He begetteth not nor was begotten\n4. And there is none comparable unto Him", "tr": "1. De ki: O Allah bir tektir\n2. Allah her şeyden müstağni ve her şey O'na muhtaçtır\n3. O doğurmamış ve doğmamıştır\n4. Hiçbir şey O'na denk değildir", "fr": "1. Dis: «Il est Allah, Unique\n2. Allah, Le Seul à être imploré pour ce que nous désirons\n3. Il n'a jamais engendré, n'a pas été engendré non plus\n4. Et nul n'est égal à Lui»", "it": "1. Di’: “Egli Allah è Unico\n2. Allah è l’Assoluto\n3. Non ha generato, non è stato generato\n4. e nessuno è eguale a Lui”", "de": "1. Sag: Er ist Allah, ein Einer\n2. Allah, der Überlegene\n3. Er hat nicht gezeugt und ist nicht gezeugt worden\n4. und niemand ist Ihm jemals gleich", "nl": "1. Zeg: \"Hij is Allah, de Enige\n2. Allah is de Enige van Wie al het geschapene afhankelijk is\n3. Hij heeft niet verwekt en is niet verwekt\n4. En niet één is aan Hem gelijkwaardig", "es": "1. Di: «¡Él es Alá, Uno\n2. Dios, el Eterno\n3. No ha engendrado, ni ha sido engendrado\n4. No tiene par»"]),
            Dhikr(id: "afterPrayer-fal", arabic: "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ\nقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ﴿١﴾\nمِنْ شَرِّ مَا خَلَقَ ﴿٢﴾\nوَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ﴿٣﴾\nوَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ﴿٤﴾\nوَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ ﴿٥﴾", ref: "Quran 113 · Al-Falaq", times: 1, translations: ["en": "1. Say: I seek refuge in the Lord of the Daybreak\n2. From the evil of that which He created\n3. From the evil of the darkness when it is intense\n4. And from the evil of malignant witchcraft\n5. And from the evil of the envier when he envieth", "tr": "De ki: \"Yaratıkların şerrinden, bastırdığı zaman karanlığın şerrinden, düğümlere nefes eden büyücülerin şerrinden, hased ettiği zaman hasedcilerin şerrinden, tan yerini ağartan Rabbe sığınırım", "fr": "1. Dis: «Je cherche protection auprès du Seigneur de l'aube naissante\n2. contre le mal des êtres qu'Il a créés\n3. contre le mal de l'obscurité quand elle s'approfondit\n4. contre le mal de celles qui soufflent [les sorcières] sur les nœuds\n5. et contre le mal de l'envieux quand il envie»", "it": "1. Di’: “Mi rifugio nel Signore dell’alba nascente\n2. contro il male che ha creato\n3. e contro il male dell’oscurità che si estende\n4. e contro il male delle soffianti sui nodi\n5. e contro il male dell’invidioso quando invidia”", "de": "1. Sag: Ich nehme Zuflucht beim Herrn des Tagesanbruchs\n2. vor dem Übel dessen, was Er erschaffen hat\n3. und vor dem Übel der Dunkelheit, wenn sie zunimmt\n4. und vor dem Übel der Knotenanbläserinnen\n5. und vor dem Übel eines (jeden) Neidenden, wenn er neidet", "nl": "1. Zeg: \"Ik zoek bescherming bij de Heer der dageraad\n2. Tegen het kwaad dat Hij geschapen heeft\n3. En tegen het kwaad van de donkere nacht wanneer hij aanbreekt\n4. En tegen het kwaad van hen die op knopen blazen\n5. En tegen het kwaad van een jaloerse wanneer deze jaloers is", "es": "1. Di: «Me refugio en el Señor del alba\n2. del mal que hacen sus criaturas\n3. del mal de la oscuridad cuando se extiende\n4. del mal de las que soplan en los nudos\n5. del mal envidioso cuando envidia»"]),
            Dhikr(id: "afterPrayer-nas", arabic: "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ\nقُلْ أَعُوذُ بِرَبِّ النَّاسِ ﴿١﴾\nمَلِكِ النَّاسِ ﴿٢﴾\nإِلَٰهِ النَّاسِ ﴿٣﴾\nمِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ﴿٤﴾\nالَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ﴿٥﴾\nمِنَ الْجِنَّةِ وَالنَّاسِ ﴿٦﴾", ref: "Quran 114 · An-Nas", times: 1, translations: ["en": "1. Say: I seek refuge in the Lord of mankind\n2. The King of mankind\n3. The god of mankind\n4. From the evil of the sneaking whisperer\n5. Who whispereth in the hearts of mankind\n6. Of the jinn and of mankind", "tr": "De ki: \"İnsanlardan ve cinlerden ve insanların gönüllerine vesvese veren o sinsi vesvesecinin şerrinden, insanların Tanrısı, insanların Hükümranı ve insanların Rabbi olan Allah'a sığınırım", "fr": "1. Dis: «Je cherche protection auprès du Seigneur des hommes\n2. Le Souverain des hommes\n3. Dieu des hommes\n4. contre le mal du mauvais conseiller, furtif\n5. qui souffle le mal dans les poitrines des hommes\n6. qu'il (le conseiller) soit un djinn, ou un être humain»", "it": "1. Di’: “Mi rifugio nel Signore degli uomini\n2. Re degli uomini\n3. Dio degli uomini\n4. contro il male del sussurratore furtivo\n5. che soffia il male nei cuori degli uomini\n6. che [venga] dai dèmoni o dagli uomini”", "de": "1. Sag: Ich nehme Zuflucht beim Herrn der Menschen\n2. dem König der Menschen\n3. dem Gott der Menschen\n4. vor dem Übel des Einflüsterers, des Davonschleichers\n5. der in die Brüste der Menschen einflüstert\n6. von den Ginn und den Menschen", "nl": "1. Zeg: \"Ik zoek bescherming bij de Heer van de mensen\n2. De Koning van de mensen\n3. De God van de mensen\n4. Tegen het kwaad van de wegsluipende influisteraar\n5. Degene die in de harten van de mensen influistert\n6. Van de Djinn's en de mensen", "es": "1. Di: «Me refugio en el Señor de los hombres\n2. el Rey de los hombres\n3. el Dios de los hombres\n4. del mal de la insinuación, del que se escabulle\n5. que insinúa en el ánimo de los hombres\n6. sea genio, sea hombre»"]),
        ]
        case "sleep": return [
            Dhikr(id: "sleep-kursi", arabic: "﴿ اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ ﴾", ref: "Quran 2:255 · Al-Baqarah", times: 1, translations: ["en": "Allah! There is no deity save Him, the Alive, the Eternal. Neither slumber nor sleep overtaketh Him. Unto Him belongeth whatsoever is in the heavens and whatsoever is in the earth. Who is he that intercedeth with Him save by His leave? He knoweth that which is in front of them and that which is behind them, while they encompass nothing of His knowledge save what He will. His throne includeth the heavens and the earth, and He is never weary of preserving them. He is the Sublime, the Tremendous", "tr": "Allah, O'ndan başka tanrı olmayan, kendisini uyuklama ve uyku tutmayan, diri, her an yaratıklarını gözetip durandır. Göklerde olan ve yerde olan ancak O'nundur. O'nun izni olmadan katında şefaat edecek kimdir? Onların işlediklerini ve işleyeceklerini bilir, dilediğinden başka ilminden hiçbir şeyi kavrayamazlar. Hükümranlığı gökleri ve yeri kaplamıştır, onların gözetilmesi O'na ağır gelmez. O yücedir, büyüktür", "fr": "Allah! Point de divinité à part Lui, le Vivant, Celui qui subsiste par lui-même «Al-Qayyûm». Ni somnolence ni sommeil ne Le saisissent. A Lui appartient tout ce qui est dans les cieux et sur la terre. Qui peut intercéder auprès de Lui sans Sa permission? Il connaît leur passé et leur futur. Et, de Sa science, ils n'embrassent que ce qu'Il veut. Son Trône «Kursiy», déborde les cieux et la terre, dont la garde ne Lui coûte aucune peine. Et Il est le Très Haut, le Très Grand", "it": "Allah! Non c'è altro dio che Lui, il Vivente, l'Assoluto. Non Lo prendon mai sopore, né sonno. A Lui appartiene tutto quello che è nei cieli e sulla terra. Chi può intercedere presso di Lui senza il Suo permesso? Egli conosce quello che è davanti a loro e quello che è dietro di loro e, della Sua scienza, essi apprendono solo ciò che Egli vuole. Il Suo Trono è più vasto dei cieli e della terra, e custodirli non Gli costa sforzo alcuno. Egli è l'Altissimo, l'Immenso", "de": "Allah - es gibt keinen Gott außer Ihm, dem Lebendigen und Beständigen. Ihn überkommt weder Schlummer noch Schlaf. Ihm gehört (alles), was in den Himmeln und was auf der Erde ist. Wer ist es denn, der bei Ihm Fürsprache einlegen könnte - außer mit Seiner Erlaubnis? Er weiß, was vor ihnen und was hinter ihnen liegt, sie aber umfassen nichts von Seinem Wissen - außer, was Er will. Sein Thronschemel umfaßt die Himmel und die Erde, und ihre Behütung beschwert Ihn nicht. Er ist der Erhabene und Allgewaltige", "nl": "Allah, er is geen god dan Hij, de Levende, de Zelfstandige, sluimer noch slaap kan Hem treffen, aan Hem behoort toe wat er in de hemelen en wat er op de aarde is. Wie is degene die van voorspraak is bij Hem zonder Zijn verlof? Hij kent wat er voor hen is en wat er achter hen is. En zij kunnen niets van Zijn Kennis omvatten, behalve wat Hij wil. En Zijn Zetel strekt zich uit over de Hemelen en de Aarde en het waken over beide vermoeit Hem niet. En Hij is de Verhevene, de Almachtige", "es": "¡Alá! No hay más dios que El. el Viviente, el Subsistente. Ni la somnolencia ni el sueño se apoderan de Él. Suyo es lo que está en los cielos y en la tierra. ¿Quién podrá interceder ante Él si no es con Su permiso? Conoce su pasado y su futuro, mientras que ellos no abarcan nada de Su ciencia, excepto lo que Él quiere. Su Trono se extiende sobre los cielos y sobre la tierra y su conservación no le resulta onerosa. Él es el Altísimo, el Grandioso"]),
            Dhikr(id: "sleep-amana", arabic: "آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ ۚ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ ۚ وَقَالُوا سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ﴿٢٨٥﴾\nلَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا ۚ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ ۗ رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ۖ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ۚ أَنْتَ مَوْلَانَا فَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ ﴿٢٨٦﴾", ref: "Quran 2:285–286 · Al-Baqarah", times: 1, translations: ["en": "285. The messenger believeth in that which hath been revealed unto him from his Lord and (so do) believers. Each one believeth in Allah and His angels and His scriptures and His messengers - We make no distinction between any of His messengers - and they say: We hear, and we obey. (Grant us) Thy forgiveness, our Lord. Unto Thee is the journeying\n286. Allah tasketh not a soul beyond its scope. For it (is only) that which it hath earned, and against it (only) that which it hath deserved. Our Lord! Condemn us not if we forget, or miss the mark! Our Lord! Lay not on us such a burden as thou didst lay on those before us! Our Lord! Impose not on us that which we have not the strength to bear! Pardon us, absolve us and have mercy on us, Thou, our Protector, and give us victory over the disbelieving folk", "tr": "285. Peygamber ve inananlar, ona Rabb'inden indirilene inandı. Hepsi Allah'a, meleklerine, kitaplarına, peygamberlerine inandı. \"Peygamberleri arasından hiçbirini ayırdetmeyiz, işittik, itaat ettik, Rabbimiz! Affını dileriz, dönüş Sanadır\" dediler\n286. Allah kişiye ancak gücünün yeteceği kadar yükler; kazandığı iyilik lehine, ettiği kötülük de aleyhinedir. Rabbimiz! Eğer unutacak veya yanılacak olursak bizi sorumlu tutma. Rabbimiz bizden öncekilere yüklediğin gibi, bize de ağır yük yükleme. Rabbimiz! Bize gücümüzün yetmeyeceği şeyi taşıtma, bizi affet, bizi bağışla, bize acı. Sen Mevlamızsın, kafirlere karşı bize yardım et", "fr": "285. Le Messager a cru en ce qu'on a fait descendre vers lui venant de son Seigneur, et aussi les croyants: tous ont cru en Allah, en Ses anges, à Ses livres et en Ses messagers; (en disant): «Nous ne faisons aucune distinction entre Ses messagers». Et ils ont dit: «Nous avons entendu et obéi. Seigneur, nous implorons Ton pardon. C'est à Toi que sera le retour»\n286. Allah n'impose à aucune âme une charge supérieure à sa capacité. Elle sera récompensée du bien qu'elle aura fait, punie du mal qu'elle aura fait. Seigneur, ne nous châtie pas s'il nous arrive d'oublier ou de commettre une erreur. Seigneur! Ne nous charge pas d'un fardeau lourd comme Tu as chargé ceux qui vécurent avant nous. Seigneur! Ne nous impose pas ce que nous ne pouvons supporter, efface nos fautes, pardonne-nous et fais nous miséricorde. Tu es Notre Maître, accorde-nous donc la victoire sur les peuples infidèles", "it": "285. Il Messaggero crede in quello che è stato fatto scendere su di lui da parte del suo Signore, come del resto i credenti: tutti credono in Allah, nei Suoi Angeli, nei Suoi Libri e nei Suoi Messaggeri. “Non facciamo differenza alcuna tra i Suoi Messaggeri.” E dicono: “Abbiamo ascoltato e obbediamo. Perdono, Signore! E’ a Te, che tutto ritorna”\n286. Allah non impone a nessun'anima al di là delle sue capacità. Quello che ognuno avrà guadagnato sarà a suo favore e ciò che avrà demeritato sarà a suo danno. “Signore, non ci punire per le nostre dimenticanze e i nostri sbagli. Signore, non caricarci di un peso grave come quello che imponesti a coloro che furono prima di noi. Signore, non imporci ciò per cui non abbiamo la forza. Assolvici, perdonaci, abbi misericordia di noi. Tu sei il nostro patrono, dacci la vittoria sui miscredenti.”", "de": "285. Der Gesandte (Allahs) glaubt an das, was zu ihm von seinem Herrn (als Offenbarung) herabgesandt worden ist, und ebenso die Gläubigen; alle glauben an Allah, Seine Engel, Seine Bücher und Seine Gesandten - Wir machen keinen Unterschied bei jemandem von Seinen Gesandten. Und sie sagen: \"Wir hören und gehorchen. (Gewähre uns) Deine Vergebung, unser Herr! Und zu Dir ist der Ausgang\n286. Allah erlegt keiner Seele mehr auf, als sie zu leisten vermag. Ihr kommt (nur) zu, was sie verdient hat, und angelastet wird ihr (nur), was sie verdient hat. \"Unser Herr, belange uns nicht, wenn wir (etwas) vergessen oder einen Fehler begehen. Unser Herr, lege uns keine Bürde auf, wie Du sie denjenigen vor uns auferlegt hast. Unser Herr, bürde uns nichts auf, wozu wir keine Kraft haben. Verzeihe uns, vergib uns und erbarme Dich unser! Du bist unser Schutzherr. So verhilf uns zum Sieg über das ungläubige Volk", "nl": "285. De Boodschapper gelooft in wat hem van zijn Heer is geopenbaard, en (ook) de gelovigen, allen geloven in Allah, en Zijn Engelen en Zijn Boeken en Zijn Boodschappers. Wij maken geen onderscheid tussen Zijn Boodschappers. Zij zeiden: \"Wij luisteren en wij gehoorzamen, vergeef ons, onze heer, en tot U is de terugkeer\n286. Allah belast niemand dan volgens zijn vermogen. Voor hem is hetgeen (de beloning) dat hij doet en voor hem is hetgeen (de bestraffing) wat hij doet. (Zeg:) \"Onze Heer, bestraf ons niet als wij vergeten of als wij fouten maken. Onze Heer, belast ons niet zoals U degenen vóór ons belast heeft. Onze Heer belast ons niet met wat wij niet kunnen dragen en scheld ons kwijt en vergeef ons en wees ons genadig. U bent onze Meester en help ons tegen het ongelovige volk", "es": "285. El Enviado cree en cuanto le ha sido revelado por su Señor, y lo mismo los creyentes. Todos ellos creen en Alá, en Sus ángeles. en Sus Escrituras y en Sus enviados. No hacemos distinción ente ninguno de Sus enviados. Han dicho: «Oímos y obedecemos. ¡Tu perdón, Señor! ¡Eres Tú el fin de todo!»\n286. Alá no pide nada a nadie más allá de sus posibilidades. Lo que uno haya hecho redundará en su propio bien o en su propio mal. ¡Señor! ¡No castigues nuestros olvidos o nuestras faltas! ¡Señor! ¡No nos impongas una carga como la que impusiste a quienes nos precedieron! ¡Señor! ¡No nos impongas más allá de nuestras fuerzas! ¡Y absuélvenos, perdónanos, apiádate d nosotros! ¡Tú eres nuestro Protector! ¡Auxílianos contra el pueblo infiel"]),
            Dhikr(id: "sleep-ikh", arabic: "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ\nقُلْ هُوَ اللَّهُ أَحَدٌ ﴿١﴾\nاللَّهُ الصَّمَدُ ﴿٢﴾\nلَمْ يَلِدْ وَلَمْ يُولَدْ ﴿٣﴾\nوَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ ﴿٤﴾", ref: "Quran 112 · Al-Ikhlas", times: 3, translations: ["en": "1. Say: He is Allah, the One\n2. Allah, the eternally Besought of all\n3. He begetteth not nor was begotten\n4. And there is none comparable unto Him", "tr": "1. De ki: O Allah bir tektir\n2. Allah her şeyden müstağni ve her şey O'na muhtaçtır\n3. O doğurmamış ve doğmamıştır\n4. Hiçbir şey O'na denk değildir", "fr": "1. Dis: «Il est Allah, Unique\n2. Allah, Le Seul à être imploré pour ce que nous désirons\n3. Il n'a jamais engendré, n'a pas été engendré non plus\n4. Et nul n'est égal à Lui»", "it": "1. Di’: “Egli Allah è Unico\n2. Allah è l’Assoluto\n3. Non ha generato, non è stato generato\n4. e nessuno è eguale a Lui”", "de": "1. Sag: Er ist Allah, ein Einer\n2. Allah, der Überlegene\n3. Er hat nicht gezeugt und ist nicht gezeugt worden\n4. und niemand ist Ihm jemals gleich", "nl": "1. Zeg: \"Hij is Allah, de Enige\n2. Allah is de Enige van Wie al het geschapene afhankelijk is\n3. Hij heeft niet verwekt en is niet verwekt\n4. En niet één is aan Hem gelijkwaardig", "es": "1. Di: «¡Él es Alá, Uno\n2. Dios, el Eterno\n3. No ha engendrado, ni ha sido engendrado\n4. No tiene par»"]),
            Dhikr(id: "sleep-fal", arabic: "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ\nقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ﴿١﴾\nمِنْ شَرِّ مَا خَلَقَ ﴿٢﴾\nوَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ﴿٣﴾\nوَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ﴿٤﴾\nوَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ ﴿٥﴾", ref: "Quran 113 · Al-Falaq", times: 3, translations: ["en": "1. Say: I seek refuge in the Lord of the Daybreak\n2. From the evil of that which He created\n3. From the evil of the darkness when it is intense\n4. And from the evil of malignant witchcraft\n5. And from the evil of the envier when he envieth", "tr": "De ki: \"Yaratıkların şerrinden, bastırdığı zaman karanlığın şerrinden, düğümlere nefes eden büyücülerin şerrinden, hased ettiği zaman hasedcilerin şerrinden, tan yerini ağartan Rabbe sığınırım", "fr": "1. Dis: «Je cherche protection auprès du Seigneur de l'aube naissante\n2. contre le mal des êtres qu'Il a créés\n3. contre le mal de l'obscurité quand elle s'approfondit\n4. contre le mal de celles qui soufflent [les sorcières] sur les nœuds\n5. et contre le mal de l'envieux quand il envie»", "it": "1. Di’: “Mi rifugio nel Signore dell’alba nascente\n2. contro il male che ha creato\n3. e contro il male dell’oscurità che si estende\n4. e contro il male delle soffianti sui nodi\n5. e contro il male dell’invidioso quando invidia”", "de": "1. Sag: Ich nehme Zuflucht beim Herrn des Tagesanbruchs\n2. vor dem Übel dessen, was Er erschaffen hat\n3. und vor dem Übel der Dunkelheit, wenn sie zunimmt\n4. und vor dem Übel der Knotenanbläserinnen\n5. und vor dem Übel eines (jeden) Neidenden, wenn er neidet", "nl": "1. Zeg: \"Ik zoek bescherming bij de Heer der dageraad\n2. Tegen het kwaad dat Hij geschapen heeft\n3. En tegen het kwaad van de donkere nacht wanneer hij aanbreekt\n4. En tegen het kwaad van hen die op knopen blazen\n5. En tegen het kwaad van een jaloerse wanneer deze jaloers is", "es": "1. Di: «Me refugio en el Señor del alba\n2. del mal que hacen sus criaturas\n3. del mal de la oscuridad cuando se extiende\n4. del mal de las que soplan en los nudos\n5. del mal envidioso cuando envidia»"]),
            Dhikr(id: "sleep-nas", arabic: "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ\nقُلْ أَعُوذُ بِرَبِّ النَّاسِ ﴿١﴾\nمَلِكِ النَّاسِ ﴿٢﴾\nإِلَٰهِ النَّاسِ ﴿٣﴾\nمِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ﴿٤﴾\nالَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ﴿٥﴾\nمِنَ الْجِنَّةِ وَالنَّاسِ ﴿٦﴾", ref: "Quran 114 · An-Nas", times: 3, translations: ["en": "1. Say: I seek refuge in the Lord of mankind\n2. The King of mankind\n3. The god of mankind\n4. From the evil of the sneaking whisperer\n5. Who whispereth in the hearts of mankind\n6. Of the jinn and of mankind", "tr": "De ki: \"İnsanlardan ve cinlerden ve insanların gönüllerine vesvese veren o sinsi vesvesecinin şerrinden, insanların Tanrısı, insanların Hükümranı ve insanların Rabbi olan Allah'a sığınırım", "fr": "1. Dis: «Je cherche protection auprès du Seigneur des hommes\n2. Le Souverain des hommes\n3. Dieu des hommes\n4. contre le mal du mauvais conseiller, furtif\n5. qui souffle le mal dans les poitrines des hommes\n6. qu'il (le conseiller) soit un djinn, ou un être humain»", "it": "1. Di’: “Mi rifugio nel Signore degli uomini\n2. Re degli uomini\n3. Dio degli uomini\n4. contro il male del sussurratore furtivo\n5. che soffia il male nei cuori degli uomini\n6. che [venga] dai dèmoni o dagli uomini”", "de": "1. Sag: Ich nehme Zuflucht beim Herrn der Menschen\n2. dem König der Menschen\n3. dem Gott der Menschen\n4. vor dem Übel des Einflüsterers, des Davonschleichers\n5. der in die Brüste der Menschen einflüstert\n6. von den Ginn und den Menschen", "nl": "1. Zeg: \"Ik zoek bescherming bij de Heer van de mensen\n2. De Koning van de mensen\n3. De God van de mensen\n4. Tegen het kwaad van de wegsluipende influisteraar\n5. Degene die in de harten van de mensen influistert\n6. Van de Djinn's en de mensen", "es": "1. Di: «Me refugio en el Señor de los hombres\n2. el Rey de los hombres\n3. el Dios de los hombres\n4. del mal de la insinuación, del que se escabulle\n5. que insinúa en el ánimo de los hombres\n6. sea genio, sea hombre»"]),
            Dhikr(id: "sleep-rabbi", arabic: "بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، فَإِن أَمْسَكْتَ نَفْسِي فارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا، بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ", ref: "Hisn al-Muslim", times: 1, translations: ["en": "In Your name, my Lord, I lay down my side, and by You I raise it. If You take my soul, have mercy on it, and if You release it, protect it as You protect Your righteous servants.", "tr": "Rabbim! Senin adınla yan tarafımı yatağa koydum, seninle de kaldırırım. Eğer canımı alırsan ona merhamet et; eğer salıverirsen salih kullarını koruduğun gibi onu da koru.", "fr": "En Ton nom, mon Seigneur, je pose mon flanc, et c’est par Toi que je le relève. Si Tu retiens mon âme, aie pitié d’elle, et si Tu la relâches, protège-la comme Tu protèges Tes serviteurs vertueux.", "it": "Nel Tuo nome, mio Signore, depongo il mio fianco, e grazie a Te lo rialzo. Se trattieni la mia anima, abbi pietà di lei, e se la rilasci, proteggila come proteggi i Tuoi servi devoti.", "de": "In Deinem Namen, mein Herr, lege ich meine Seite nieder, und durch Dich erhebe ich sie. Wenn Du meine Seele zurückhältst, so erbarme Dich ihrer, und wenn Du sie freigibst, so bewahre sie, wie Du Deine rechtschaffenen Diener bewahrst.", "nl": "In Uw naam, mijn Heer, leg ik mijn zijde neer, en door U richt ik haar weer op. Als U mijn ziel terughoudt, wees haar dan barmhartig, en als U haar loslaat, bescherm haar dan zoals U Uw rechtschapen dienaren beschermt.", "es": "En Tu nombre, Señor mío, apoyo mi costado, y por Ti lo levanto. Si retienes mi alma, ten misericordia de ella, y si la dejas ir, protégela como proteges a Tus siervos justos."]),
            Dhikr(id: "sleep-amutu", arabic: "بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا", ref: "Hisn al-Muslim", times: 1, translations: ["en": "In Your name, O Allah, I die and I live.", "tr": "Allah’ım! Senin adınla ölür ve dirilirim.", "fr": "En Ton nom, ô Allah, je meurs et je vis.", "it": "Nel Tuo nome, o Allah, muoio e vivo.", "de": "In Deinem Namen, o Allah, sterbe ich und lebe ich.", "nl": "In Uw naam, o Allah, sterf ik en leef ik.", "es": "En Tu nombre, oh Allah, muero y vivo."]),
            Dhikr(id: "sleep-subhanallah", arabic: "سُبْحَانَ اللَّهِ", ref: "Hisn al-Muslim", times: 33, translations: ["en": "Glory be to Allah.", "tr": "Allah’ı tesbih ederim.", "fr": "Gloire à Allah.", "it": "Gloria ad Allah.", "de": "Gepriesen sei Allah.", "nl": "Glorie zij Allah.", "es": "Gloria a Allah."]),
            Dhikr(id: "sleep-alhamdulillah", arabic: "الْحَمْدُ لِلَّهِ", ref: "Hisn al-Muslim", times: 33, translations: ["en": "All praise is for Allah.", "tr": "Hamd Allah’a mahsustur.", "fr": "Louange à Allah.", "it": "La lode è per Allah.", "de": "Alles Lob gebührt Allah.", "nl": "Alle lof zij Allah.", "es": "La alabanza es para Allah."]),
            Dhikr(id: "sleep-akbar", arabic: "اللَّهُ أَكْبَرُ", ref: "Hisn al-Muslim", times: 34, translations: ["en": "Allah is the Greatest.", "tr": "Allah en büyüktür.", "fr": "Allah est le Plus Grand.", "it": "Allah è il più grande.", "de": "Allah ist der Größte.", "nl": "Allah is de Grootste.", "es": "Allah es el más grande."]),
            Dhikr(id: "sleep-wake", arabic: "الْحَمْدُ للَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا، وَإِلَيْهِ النُّشُورُ", ref: "Hisn al-Muslim", times: 1, translations: ["en": "All praise is for Allah who gave us life after causing us to die, and to Him is the resurrection.", "tr": "Bizi öldürdükten sonra dirilten Allah’a hamdolsun; dönüş ancak O’nadır.", "fr": "Louange à Allah qui nous a rendu la vie après nous avoir fait mourir, et c’est vers Lui que sera la résurrection.", "it": "La lode è per Allah che ci ha restituito la vita dopo averci fatto morire, e a Lui sarà la resurrezione.", "de": "Alles Lob gebührt Allah, der uns wieder lebendig gemacht hat, nachdem Er uns hat sterben lassen, und zu Ihm ist die Auferstehung.", "nl": "Alle lof zij Allah die ons het leven heeft teruggegeven nadat Hij ons had laten sterven, en tot Hem is de opstanding.", "es": "La alabanza es para Allah, que nos dio la vida después de hacernos morir, y a Él será la resurrección."]),
        ]
        case "travel": return [
            Dhikr(id: "travel-travel", arabic: "اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، ﴿سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَى رَبِّنَا لَمُنقَلِبُونَ﴾ اللَّهُمَّ إِنّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا البِرَّ وَالتَّقْوَى، وَمِنَ الْعَمَلِ مَا تَرْضَى، اللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا وَاطْوِ عَنَّا بُعْدَهُ، اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ، وَالْخَليفَةُ فِي الْأَهْلِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ، وَكَآبَةِ الْمَنْظَرِ، وَسُوءِ الْمُنْقَلَبِ فِي الْمَالِ وَالْأَهْلِ، وَإِذَا رَجَعَ قَالَهُنَّ وَزَادَ فِيهِنَّ: آيِبُونَ، تائِبُونَ، عَابِدُونَ، لِرَبِّنَا حَامِدُونَ", ref: "Hisn al-Muslim", times: 1, translations: ["en": "Allah is the Greatest, Allah is the Greatest, Allah is the Greatest. Glory be to Him who has subjected this to us, and we could never have done it ourselves, and to our Lord we shall surely return. O Allah, we ask You on this journey of ours for righteousness and piety, and for deeds that please You. O Allah, make this journey easy for us and shorten its distance for us. O Allah, You are the Companion on the journey and the Guardian of the family. O Allah, I seek refuge in You from the hardship of travel, from a sad sight, and from an evil return in wealth and family. When returning, say the same and add: We return, repenting, worshipping, and praising our Lord.", "tr": "Allah en büyüktür, Allah en büyüktür, Allah en büyüktür. Bunu bizim buyruğumuza veren Allah’ı tesbih ederiz; yoksa biz buna güç yetiremezdik. Şüphesiz biz Rabbimize döneceğiz. Allah’ım! Bu yolculuğumuzda senden iyilik, takva ve razı olacağın ameller dileriz. Allah’ım! Bu yolculuğumuzu bize kolaylaştır, uzaklığını bizim için dürüp kısalt. Allah’ım! Yolculukta sen yoldaşsın, ailede de sen vekilsin. Allah’ım! Yolculuğun zorluğundan, kederli bir manzaradan, mal ve ailede kötü bir dönüşten sana sığınırım. Dönüşte aynısını söyler ve şunu ekler: Dönenleriz, tövbe edenleriz, ibadet edenleriz, Rabbimize hamd edenleriz.", "fr": "Allah est le Plus Grand, Allah est le Plus Grand, Allah est le Plus Grand. Gloire à Celui qui nous a soumis cela alors que nous n’aurions pu le faire par nous-mêmes, et c’est vers notre Seigneur que nous retournerons. Ô Allah, nous Te demandons, pour ce voyage, la piété et la crainte révérencielle, ainsi que des actes qui Te plaisent. Ô Allah, facilite-nous ce voyage et raccourcis-nous sa distance. Ô Allah, Tu es le Compagnon du voyage et le Garant de la famille. Ô Allah, je cherche refuge auprès de Toi contre les difficultés du voyage, contre un spectacle attristant et contre un mauvais retour concernant les biens et la famille. Au retour, on dit la même chose en ajoutant : Nous revenons, repentants, adorateurs, louant notre Seigneur.", "it": "Allah è il più grande, Allah è il più grande, Allah è il più grande. Gloria a Colui che ci ha sottomesso questo, mentre noi non saremmo stati capaci di farlo, e a nostro Signore faremo ritorno. O Allah, Ti chiediamo in questo nostro viaggio la pietà e il timore reverenziale, e opere che Ti siano gradite. O Allah, rendici facile questo viaggio e accorcia la sua distanza. O Allah, Tu sei il Compagno nel viaggio e il Custode della famiglia. O Allah, cerco rifugio in Te dalle difficoltà del viaggio, da una vista triste e da un cattivo ritorno nei beni e nella famiglia. Al ritorno si dice lo stesso aggiungendo: Siamo di ritorno, pentiti, adoranti, lodando il nostro Signore.", "de": "Allah ist der Größte, Allah ist der Größte, Allah ist der Größte. Gepriesen sei Der, Der uns dies dienstbar gemacht hat, wo wir dazu selbst nicht fähig gewesen wären, und zu unserem Herrn werden wir zurückkehren. O Allah, wir bitten Dich auf dieser unserer Reise um Frömmigkeit und Gottesfurcht und um Taten, die Dir wohlgefällig sind. O Allah, mache uns diese Reise leicht und verkürze uns ihre Entfernung. O Allah, Du bist der Begleiter auf der Reise und der Beschützer der Familie. O Allah, ich suche Zuflucht bei Dir vor den Strapazen der Reise, vor einem traurigen Anblick und vor einer schlimmen Heimkehr in Besitz und Familie. Bei der Rückkehr spricht man dasselbe und fügt hinzu: Wir kehren zurück, reuig, anbetend, unseren Herrn lobpreisend.", "nl": "Allah is de Grootste, Allah is de Grootste, Allah is de Grootste. Glorie zij Hem Die ons dit dienstbaar heeft gemaakt, terwijl wij dat zelf nooit hadden gekund, en tot onze Heer zullen wij terugkeren. O Allah, wij vragen U op deze reis van ons om vroomheid en godvrezendheid, en om daden die U behagen. O Allah, maak deze reis gemakkelijk voor ons en verkort de afstand ervan. O Allah, U bent de Metgezel op reis en de Behoeder van het gezin. O Allah, ik zoek toevlucht bij U tegen de ontberingen van de reis, tegen een treurig gezicht en tegen een slechte terugkeer wat betreft bezit en gezin. Bij de terugkeer zegt men hetzelfde en voegt men toe: Wij keren terug, berouwvol, aanbiddend, onze Heer lovend.", "es": "Allah es el más grande, Allah es el más grande, Allah es el más grande. Gloria a Quien nos ha sometido esto, pues nosotros no habríamos podido hacerlo, y a nuestro Señor regresaremos. Oh Allah, Te pedimos en este viaje nuestro piedad y temor reverencial, y obras que Te agraden. Oh Allah, facilítanos este viaje y acorta su distancia. Oh Allah, Tú eres el Compañero en el viaje y el Guardián de la familia. Oh Allah, me refugio en Ti de las dificultades del viaje, de una visión triste y de un mal regreso en bienes y familia. Al regresar se dice lo mismo añadiendo: Regresamos arrepentidos, adorando y alabando a nuestro Señor."]),
            Dhikr(id: "travel-stop", arabic: "أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ", ref: "Hisn al-Muslim", times: 1, translations: ["en": "I seek refuge in the perfect words of Allah from the evil of what He has created.", "tr": "Allah’ın eksiksiz kelimelerine sığınırım, yarattığı şeylerin şerrinden.", "fr": "Je cherche refuge dans les paroles parfaites d’Allah contre le mal de ce qu’Il a créé.", "it": "Cerco rifugio nelle parole perfette di Allah dal male di ciò che Egli ha creato.", "de": "Ich suche Zuflucht bei den vollkommenen Worten Allahs vor dem Bösen dessen, was Er erschaffen hat.", "nl": "Ik zoek toevlucht bij de volmaakte woorden van Allah tegen het kwaad van wat Hij heeft geschapen.", "es": "Me refugio en las palabras perfectas de Allah del mal de lo que Él ha creado."]),
        ]
        default: return []
        }
    }
}
